/* ── Tokens ── GENERATED from src/tokens.ts. Do not edit by hand. */
:root {
  --bg: #FAF8F2;                        /* paper */
  --text: #1A1A1A;                      /* ink */
  --text-secondary: #6B6B6B;            /* gray */
  --accent: #1A1A1A;                   /* the "accent" is ink; monochrome */
  --divider: rgba(0,0,0,0.10);
  --divider-subtle: rgba(0,0,0,0.06);
  --table-alt: rgba(0,0,0,0.02);
  --grid-line: rgba(0,0,0,0.025);
  --radius: 6px;
  --radius-sm: 4px;
  --radius-chrome: 0px;
  --gutter: 20px;
  --pad: 20px;
  /* Concentric: inner = max(0, outer − padding). Default radius vs --pad is 0. */
  --radius-in: max(0px, calc(var(--radius) - var(--pad)));
  --ease: cubic-bezier(0.2, 0, 0, 1);
  --duration-snap: 0.12s;
  --duration: 0.18s;
  --duration-confirm: 0.16s;
  --transition: background-color var(--duration) var(--ease), color var(--duration) var(--ease);
  /* Background column grid: 204px modules (184 column + 20 gutter). */
  --grid-image: linear-gradient(to right,var(--grid-line) 0,var(--grid-line) 1px,transparent 1px,transparent 184px,var(--grid-line) 184px,var(--grid-line) 185px,transparent 185px,transparent 204px);
  --grid-size: 204px;
  --grid-pos: 20px 0;
  /* Control scale. Desktop is the Raster poster; phone recuts in phone.css. */
  --hit: 40px;
  --control-h: 40px;
  --control-fs: 14px;
  --control-label: 12px;
}
[data-theme="dark"] {
  --bg: #0E0C0A;
  --text: #E8E8E8;
  --text-secondary: #949494;
  --accent: #E8E8E8;
  --divider: rgba(255,255,255,0.12);
  --divider-subtle: rgba(255,255,255,0.07);
  --table-alt: rgba(255,255,255,0.03);
  --grid-line: rgba(255,255,255,0.01);
}
/* Mobile grid (≤480): two fluid columns, three 25px gutters
   (edge · middle · edge). Column width = 50vw − 37.5px; the background
   draws all four column-edge lines and content lives between the outer pair. */
@media(max-width:480px){
  :root{
    --pad:25px;
    --grid-image:linear-gradient(to right,transparent 0,transparent 25px,var(--grid-line) 25px,var(--grid-line) 26px,transparent 26px,transparent calc(50vw - 12.5px),var(--grid-line) calc(50vw - 12.5px),var(--grid-line) calc(50vw - 11.5px),transparent calc(50vw - 11.5px),transparent calc(50vw + 12.5px),var(--grid-line) calc(50vw + 12.5px),var(--grid-line) calc(50vw + 13.5px),transparent calc(50vw + 13.5px),transparent calc(100vw - 26px),var(--grid-line) calc(100vw - 26px),var(--grid-line) calc(100vw - 25px),transparent calc(100vw - 25px));
    --grid-size:100vw;
    --grid-pos:0 0;
  }
}
/* Phone control scale (≤640): 44pt hits, 16px type on fields. */
@media(max-width:640px){
  :root{
    --hit:44px;
    --control-h:44px;
    --control-fs:16px;
    --control-label:15px;
  }
}

/* ── Base ──
   Raster owns the page: paper background, ink text, and the visible
   204px module grid drawn behind everything. */
html{scroll-behavior:smooth;font-size:16px;overflow-x:clip}
body{
  overflow-x:clip;
  background-color:var(--bg);
  background-image:var(--grid-image);
  background-size:var(--grid-size) 100vh;
  background-repeat:repeat-x;
  background-attachment:fixed;
  background-position:var(--grid-pos);
  color:var(--text);
  font-family:Inter,-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;
  font-weight:500;
  line-height:1.6;
  transition:var(--transition);
  -webkit-font-smoothing:antialiased;
}

/* ── Utilities ── */
.rs-sr{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.rs-sr:focus-visible+.rs-check,.rs-sr:focus-visible+.rs-radio-dot,.rs-sr:focus-visible+.rs-switch{outline:1.5px solid var(--text);outline-offset:2px}

/* ── Type scale ──
   Hierarchy from weight, color, and position; never all caps. */
.rs-t-xl{font-size:clamp(34px,5vw,52px);font-weight:600;letter-spacing:-.035em;line-height:1.05;color:var(--text);margin:0;text-wrap:balance}
.rs-t-display{font-size:38px;font-weight:600;letter-spacing:-.03em;line-height:1.15;color:var(--text);margin:0;text-wrap:balance}
.rs-t-title{font-size:22px;font-weight:600;letter-spacing:-.02em;line-height:1.3;color:var(--text);margin:0;text-wrap:balance}
.rs-t-sub{font-size:17px;font-weight:500;letter-spacing:-.01em;line-height:1.5;color:var(--text-secondary);margin:0;text-wrap:pretty}
.rs-t-body{font-size:15px;font-weight:500;letter-spacing:-.01em;line-height:1.6;color:var(--text);margin:0;text-wrap:pretty}
.rs-t-label{font-size:13px;font-weight:600;letter-spacing:-.01em;line-height:1.3;color:var(--text);margin:0}

/* ── Inline code ── */
.rs-code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.88em;color:var(--text);background:var(--table-alt);padding:1px 5px;border-radius:var(--radius-sm);letter-spacing:0}

/* ── Phone scale (≤640): iOS Human Interface, translated into Raster.
   Desktop rules in components/*.css stay the poster. Do not restyle ≥900. ── */
@media(max-width:640px){
  /* Button: full-width 44pt, 16px, flush. Small variant grows with the scale. */
  .rs-btn-primary,.rs-btn-ghost{
    width:100%;
    height:var(--control-h);
    min-height:var(--hit);
    font-size:var(--control-fs);
    padding:0 20px;
    border-radius:0;
  }
  .rs-btn-sm{height:var(--control-h);min-height:var(--hit);font-size:var(--control-fs);padding:0 16px;min-width:0}
  .rs-btn-group{display:flex;width:100%}
  .rs-btn-group>.rs-btn-primary,.rs-btn-group>.rs-btn-ghost{flex:1;min-width:0}

  /* Field / input: 16px so iOS does not zoom; 44pt hit; label steps up. */
  .rs-field{gap:8px}
  .rs-field-label,.rs-label{font-size:var(--control-label)}
  .rs-input{
    min-height:var(--hit);
    font-size:16px;
    padding:12px 14px;
    border-radius:0;
  }
  .rs-feedback,.rs-field-hint,.rs-field-error{font-size:14px;margin-top:4px}
  .rs-form{max-width:none;width:100%;gap:20px}

  /* Textarea / native select */
  .rs-textarea{font-size:16px;padding:12px 14px;border-radius:0;min-height:132px}
  .rs-native-select{min-height:var(--hit);font-size:16px;padding:12px 36px 12px 14px;border-radius:0}

  /* Checkbox / radio: 44pt rows, larger mark, 17px label */
  .rs-choice,.rs-radio{
    min-height:var(--hit);
    font-size:17px;
    gap:12px;
  }
  .rs-check{width:22px;height:22px;border-radius:0}
  .rs-check svg{width:16px;height:16px}
  .rs-radio-dot{width:22px;height:22px}
  .rs-radio-on::after{inset:5px}

  /* Switch: square Raster track, not the desktop pill. 44pt hit. */
  .rs-switch,button.rs-switch{
    width:64px;
    height:var(--hit);
    min-width:64px;
    min-height:var(--hit);
    border-radius:0;
    box-sizing:border-box;
  }
  .rs-switch i{
    top:4px;
    left:4px;
    width:36px;
    height:36px;
    border-radius:0;
  }
  .rs-switch-on i{transform:translateX(20px)}

  /* Tabs: full-width equal columns, 44pt, hairline under the set */
  .rs-tabs{
    display:flex;
    align-items:stretch;
    width:100%;
    max-width:none;
    gap:0;
    border-bottom:1px solid var(--divider);
  }
  .rs-tab,button.rs-tab{
    flex:1;
    display:inline-flex;
    align-items:center;
    justify-content:center;
    min-height:var(--hit);
    padding:0 8px;
    font-size:var(--control-fs);
    text-align:center;
  }

  /* Stepper: 44pt marks, 16px names, more air. Already stacks at 640. */
  .rs-steps{gap:20px}
  .rs-step{min-width:0;gap:6px}
  .rs-step-dot{
    width:var(--hit);
    height:var(--hit);
    border-radius:0;
    font-size:15px;
    margin-bottom:8px;
  }
  .rs-step-name{font-size:var(--control-fs)}
  .rs-step-sub{font-size:13px}

  /* Accordion / collapsible: 44pt headers, 17px */
  .rs-acc-item summary{
    min-height:var(--hit);
    padding:14px 0;
    font-size:17px;
  }
  .rs-acc-body{padding:0 0 20px;font-size:16px}
  .rs-disclosure summary{
    min-height:var(--hit);
    font-size:17px;
  }
  .rs-disclosure-body{font-size:16px;padding:12px 0 0}

  /* Menu / select / combobox: 44pt trigger and rows, sheet-like overlay */
  .rs-select,.rs-combobox{width:100%;min-width:0;display:block}
  .rs-dropdown,button.rs-dropdown{
    min-height:var(--hit);
    font-size:var(--control-fs);
    padding:12px 14px;
    border-radius:0;
  }
  .rs-menu{
    border-radius:0;
    box-shadow:none;
    margin-top:0;
  }
  .rs-menu-item,button.rs-menu-item{
    min-height:var(--hit);
    font-size:var(--control-fs);
    padding:12px 14px;
    display:flex;
    align-items:center;
  }
  .rs-combobox-empty{padding:14px;font-size:15px}

  /* Toggle / segmented: full-width 44pt bar, flush */
  .rs-toggle{
    height:var(--hit);
    min-height:var(--hit);
    min-width:var(--hit);
    padding:0 14px;
    font-size:var(--control-fs);
    border-radius:0;
  }
  .rs-toggle-group{display:flex;width:100%}
  .rs-toggle-group .rs-toggle{flex:1;border-radius:0;margin-left:-1px}
  .rs-toggle-group .rs-toggle:first-child{border-radius:0;margin-left:0}
  .rs-toggle-group .rs-toggle:last-child{border-radius:0}

  /* Slider: thicker track, larger thumb, ±20px hit */
  .rs-slider{height:4px;margin:20px 0;border-radius:0}
  .rs-slider-fill{border-radius:0}
  .rs-slider-thumb{width:22px;height:22px;border-radius:0}
  .rs-slider input[type=range]{top:-20px;bottom:-20px}

  /* Pagination + carousel / calendar nav (they reuse .rs-page) */
  .rs-pages{gap:8px;flex-wrap:wrap}
  .rs-page,button.rs-page{
    width:var(--hit);
    height:var(--hit);
    min-width:var(--hit);
    min-height:var(--hit);
    font-size:var(--control-fs);
    border-radius:0;
  }
  .rs-carousel-nav{gap:8px;margin-top:14px}

  /* Toast: full-width bottom sheet, no shadow, 0 radius */
  .rs-toasts{
    left:0;
    right:0;
    bottom:0;
    align-items:stretch;
    gap:0;
  }
  .rs-toast{
    max-width:none;
    width:100%;
    border-radius:0;
    box-shadow:none;
    padding:16px 20px;
    padding-bottom:calc(16px + env(safe-area-inset-bottom,0px));
  }
  .rs-toast-title{font-size:16px}
  .rs-toast-body{font-size:15px;margin-top:4px}
  .rs-toast-action,.rs-toast .rs-btn-ghost,.rs-toast .rs-btn-primary{
    min-height:var(--hit);
    font-size:var(--control-fs);
  }

  /* Chip: 44pt identifier, more air */
  .rs-chip{
    display:inline-flex;
    align-items:center;
    min-height:var(--hit);
    padding:12px 14px;
    font-size:13px;
    border-radius:0;
  }

  /* Item: 44pt+ cells, 16px title */
  .rs-item{min-height:var(--hit);padding:14px 0}
  .rs-item-title{font-size:var(--control-fs)}
  .rs-item-desc{font-size:14px}
  .rs-item-meta{font-size:14px}

  /* Command: 44pt input and rows */
  .rs-command{width:100%;max-width:100%}
  .rs-command-input{min-height:var(--hit);font-size:16px;padding:14px 16px}
  .rs-command-item{
    min-height:var(--hit);
    font-size:var(--control-fs);
    padding:12px 14px;
    border-radius:0;
  }
  .rs-command-group{font-size:13px;padding:12px 14px 6px}
  .rs-command-empty{padding:24px;font-size:15px}

  /* Inline form: field + action share a 44pt row */
  .rs-inline-field{min-height:var(--hit);padding:0;border-radius:0;align-items:stretch}
  .rs-inline-input{font-size:16px;padding:0 14px;min-height:var(--hit)}
  .rs-inline-btn{height:var(--hit);min-height:var(--hit);font-size:var(--control-fs);padding:0 16px;border-radius:0}

  /* OTP / input group */
  .rs-otp{width:100%;gap:8px}
  .rs-otp input{flex:1;width:auto;min-width:0;min-height:var(--hit);height:var(--hit);font-size:18px;border-radius:0}
  .rs-input-group{border-radius:0}
  .rs-input-addon{min-height:var(--hit);padding:0 14px;font-size:var(--control-fs)}
  .rs-input-group .rs-input{min-height:var(--hit)}

  /* Nav / menubar / breadcrumbs */
  .rs-nav{flex-wrap:wrap;gap:0}
  .rs-nav a{
    display:inline-flex;
    align-items:center;
    min-height:var(--hit);
    padding:0 12px;
    font-size:var(--control-fs);
  }
  .rs-menubar{width:100%;padding:0;border-radius:0}
  .rs-menubar .rs-dropdown{min-height:var(--hit);padding:12px 14px;font-size:var(--control-fs)}
  .rs-crumbs{font-size:var(--control-fs);flex-wrap:wrap;align-items:center;gap:6px}
  .rs-crumbs a,.rs-crumbs .rs-crumbs-link,.rs-crumbs-here{
    display:inline-flex;
    align-items:center;
    min-height:var(--hit);
  }

  /* Calendar: full width, 44×44 days */
  .rs-cal{width:100%}
  .rs-cal-title{font-size:var(--control-fs)}
  .rs-cal-nav{gap:8px}
  .rs-cal-grid{grid-template-columns:repeat(7,minmax(0,1fr));width:100%}
  .rs-cal-dow{font-size:13px;padding:8px 0}
  .rs-cal-day{
    width:100%;
    height:var(--hit);
    min-height:var(--hit);
    font-size:var(--control-fs);
    border-radius:0;
  }

  /* Sidebar: 44pt rows, 16px. Desktop padding:8px 0 32px stays in sidebar.css. */
  .rs-sidebar{width:100%}
  .rs-sidebar-head{font-size:var(--control-fs);padding:16px 20px;min-height:var(--hit);display:flex;align-items:center}
  .rs-sidebar-item,.rs-sidebar-item:link,.rs-sidebar-item:visited,.rs-sidebar-item:any-link{
    display:flex;
    align-items:center;
    min-height:var(--hit);
    padding:12px 20px;
    font-size:var(--control-fs);
  }
  .rs-sidebar-item:last-child{padding-bottom:32px}
  .rs-sidebar-label{font-size:var(--control-label);padding:16px 20px 8px}
  .rs-sidebar-foot{font-size:14px;min-height:var(--hit);display:flex;align-items:center}

  /* Dialog / alert-dialog: near-full width, stacked actions, no shadow */
  .rs-dialog{
    max-width:calc(100vw - 32px);
    width:calc(100vw - 32px);
    border-radius:0;
    box-shadow:none;
    padding:24px 20px;
  }
  .rs-dialog-title{font-size:18px;margin-bottom:10px}
  .rs-dialog-body{font-size:16px;margin:0 0 20px}
  .rs-dialog-actions{flex-direction:column;align-items:stretch;gap:10px}

  /* Sheet: full width, no shadow */
  dialog.rs-sheet{
    width:100%;
    max-width:100%;
    box-shadow:none;
    padding:24px 20px;
  }
  .rs-sheet-title{font-size:18px}
  .rs-sheet-body{font-size:16px}

  /* Drawer type */
  .rs-drawer-title{font-size:18px}
  .rs-drawer-body{font-size:16px}

  /* Popover: wider, 16px, flush */
  .rs-popover{width:min(320px,calc(100vw - 32px));font-size:16px;border-radius:0;box-shadow:none;padding:16px}
  .rs-popover-title{font-size:16px}

  /* Table: undo the 12px shrink; 44pt-ish rows */
  .rs-table{font-size:16px}
  .rs-table th{padding:14px 12px;font-size:15px}
  .rs-table td{padding:14px 12px;font-size:16px}

  /* Split: stack panes; 44pt row handle */
  .rs-split{flex-direction:column}
  .rs-split-handle{
    width:auto;
    height:var(--hit);
    margin:-4px 0;
    cursor:row-resize;
  }
  .rs-split-handle::after{left:0;right:0;top:50%;bottom:auto;width:auto;height:1px}

  /* Theme toggle (library): 44pt. Site chrome uses .theme-toggle separately. */
  .rs-theme-toggle{width:var(--hit);height:var(--hit);min-width:var(--hit);min-height:var(--hit);padding:12px}

  /* Empty action stretches with the primary */
  .rs-empty-action{width:100%}

  /* Hover card / tooltip type on phone */
  .rs-hover-card-panel{width:min(280px,calc(100vw - 32px));font-size:15px;border-radius:0;box-shadow:none}
  .rs-tip::after{font-size:13px;padding:8px 12px;border-radius:0}
}

/* Touch: no hover-only reveal. Focus / press shows the overlay. */
@media(hover:none){
  .rs-btn-primary:hover{opacity:1}
  .rs-btn-primary:active{opacity:.85}
  .rs-btn-ghost:hover{background:transparent;border-color:var(--divider)}
  .rs-btn-ghost:active{background:var(--divider);border-color:transparent}
  .rs-cal-day:hover{background:none}
  .rs-cal-day:active{background:var(--divider-subtle)}
  .rs-hover-card:hover .rs-hover-card-panel{opacity:0;visibility:hidden}
  .rs-hover-card:focus-within .rs-hover-card-panel,
  .rs-hover-card:active .rs-hover-card-panel{opacity:1;visibility:visible}
  .rs-tip:hover::after{opacity:0}
  .rs-tip:focus-within::after,
  .rs-tip:active::after{opacity:1}
  .rs-link:hover{border-color:var(--divider)}
  .rs-link:active{border-color:var(--accent)}
  .rs-link-underline:hover{background-image:linear-gradient(var(--divider),var(--divider))}
  .rs-link-underline:active{background-image:linear-gradient(var(--accent),var(--accent))}
}

/* ── Reduced motion: nothing loops, nothing slides, nothing enters ── */
@media(prefers-reduced-motion:reduce){
  .rs-reveal,.rs-crumb-bar .rs-crumbs,.rs-tip::after,.rs-hover-card-panel{transition:none}
  .rs-subscribed,.rs-toast{animation:none}
  .rs-theme-track,.rs-theme-sun,.rs-theme-moon{transition:none}
  .rs-spinner{animation:none;border-top-color:var(--text)}
}
